UPDATE entidades SET nombre='Castillo de Lanjarón', descripcion='Siglos XIII-XIV. Impresionante fortaleza roquera medieval emplazada de forma inverosímil sobre una colosal e inaccesible aguja de roca caliza vertical que domina la entrada a la Alpujarra alta. De origen nazarí, conserva su Torre del Homenaje de sillería, murallas almenadas encajadas en el risco calcáreo y aljibes.' WHERE id=87433;
